const [cx,cy]=L.checkpoint;if(!checkpoint&&p.ground&&Math.abs(p.x+14-cx)<35&&Math.abs(p.y+p.h-cy)<2){checkpoint=true;$('checkpoint').textContent='⚑ 检查点已激活';say('检查点已激活！失误后从绿旗继续。');tone(650,.15);}
